package argv

import (
	"reflect"
	"testing"
)

func TestLokiSpec_C1_BareDashKeepsOperands(t *testing.T) {
	want := []string{"-", "foo", "bar"}
	if got := Split([]string{"-", "foo", "bar"}).Args; !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v want %#v", got, want)
	}
}

func TestLokiSpec_P1_PaddedBareDash(t *testing.T) {
	want := []string{" - ", "x"}
	if got := Split([]string{" - ", "x"}).Args; !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v want %#v", got, want)
	}
}
